"""Record the visual review performed on all 16 atlases and 11 ROI supplements."""
from common import *
from collections import Counter
M=BASE/'mapping';summary=read(M/'nhan_thong_ke.csv');samples=read(M/'atlas_samples.csv')
names=['Nền','Áo thân trên','Chân váy / váy ngắn','Tất / quần tất','Mặt','Váy liền','Túi / dây túi','Trang sức / phụ kiện nhỏ','Áo khoác / lớp ngoài','Tóc','Mũ / đồ đội đầu','Kính','Thắt lưng / áo buộc eo','Quần dài / quần ngắn','Da / tay / chân / cổ','Giày / dép / bốt']
groups=['nen','quan-ao','quan-ao','quan-ao','da-mat-toc','quan-ao','giay-phu-kien','giay-phu-kien','quan-ao','da-mat-toc','giay-phu-kien','giay-phu-kien','giay-phu-kien','quan-ao','da-mat-toc','giay-phu-kien']
notes={0:'Vùng ngoài người/đồ; mask thiếu có thể gán đồ vào nền, không bảo đảm mọi pixel nền đúng.',1:'Áo đa dạng, kể cả hoodie; nhóm quần áo rõ.',2:'Chủ yếu chân váy; vài mẫu quần ngắn giống váy. Phân biệt subtype chưa chắc nhưng cùng nhóm giữ.',3:'Trung bình-cao ở quyết định giữ nhóm tất/quần tất: nhiều mẫu rõ, ROI bổ sung xác nhận. Có ngoại lệ 1361_021 (vùng mặt), 3746_071 (mảng gần đầu); không gọi mọi pixel đúng.',4:'Đa số vùng mặt; 1247_171 có vùng quần lẫn cùng nhãn. ROI bổ sung nhất quán mặt.',5:'Váy liền, kể cả váy dài; khác ranh giới cổ/tay không đổi nhóm.',6:'Túi/ví/ba lô, đôi lúc chỉ thấy dây túi.',7:'Vòng cổ, vòng tay, đồng hồ, khuyên tai, nhẫn; tên loại chi tiết thay đổi nhưng đều phụ kiện. ROI giúp thấy vùng nhỏ.',8:'Áo khoác/cardigan/lớp ngoài, cả cầm tay hoặc khoác ở khuỷu; vẫn quần áo.',9:'Tóc; có biên lẫn nền/da. Không thấy đổi nhóm có hệ thống giữa split.',10:'Mũ rõ trong phần lớn mẫu; vài ảnh mảnh rất nhỏ khó nhận diện, không khẳng định mọi pixel.',11:'Kính gọng/kính râm, vùng mắt; ROI bổ sung rõ.',12:'Cả thắt lưng và áo buộc quanh eo; tên không đồng nhất nhưng đều quần áo/phụ kiện giữ lại.',13:'Quần nhiều độ dài; ngoại lệ 1453_021 khoanh cả hoodie, vẫn quần áo nhưng subtype sai.',14:'Da ở tay/chân/cổ/thân; ngoại lệ 1696_051 và 1741_071 gán lẫn váy. Không phải mask hoàn hảo.',15:'Giày/dép/bốt; ROI 3664_042 chỉ lộ miệng bốt/tất, vẫn nhóm giữ.'}
proposal=[];review=[];stability=[]
for v in range(16):
 allr=next(r for r in summary if int(r['nhan'])==v and r['split']=='all');ss=[r for r in summary if int(r['nhan'])==v and r['split']!='all'];sc=[r for r in samples if int(r['label'])==v];extra=any(r['kind']=='extra_roi' for r in sc);conf='trung_binh' if v==3 else 'cao';paths=[f'atlas_nhan_{v:02d}.png']+([f'bo_sung_nhan_{v:02d}.png'] if extra else [])
 evidence=f"{'; '.join(paths)}; đã xem {len(sc)} ô; {allr['so_anh']} ảnh có nhãn; tâm y={float(allr['tam_y_tb']):.6f}, diện tích TB={float(allr['dien_tich_tb_ty_le']):.6f}; nhan_thong_ke.csv"
 proposal.append({'nhan':v,'ten_vung_de_xuat':names[v],'nhom':groups[v],'do_tin_cay':conf,'bang_chung':evidence,'ghi_chu':notes[v]})
 review.append({'label':v,'reviewed_main_cells':sum(r['kind']=='random24' for r in sc),'reviewed_extra_cells':sum(r['kind']=='extra_roi' for r in sc),'files_opened':paths,'assessment':notes[v],'confidence_scope':'coarse semantic group for keep/drop; not percentage accuracy or official mapping'})
 stability.append({'label':v,'range_mean_area':max(float(r['dien_tich_tb_ty_le']) for r in ss)-min(float(r['dien_tich_tb_ty_le']) for r in ss),'range_centroid_x':max(float(r['tam_x_tb']) for r in ss)-min(float(r['tam_x_tb']) for r in ss),'range_centroid_y':max(float(r['tam_y_tb']) for r in ss)-min(float(r['tam_y_tb']) for r in ss)})
write(M/'mapping_de_xuat.csv',proposal);write(M/'on_dinh_giua_split.csv',stability);dump(M/'visual_review_log.json',review)
keep=[v for v,g in enumerate(groups) if g in ['quan-ao','giay-phu-kien']];dump(M/'decision.json',{'proceed':True,'keep_labels':keep,'drop_labels':[0,4,9,14],'ambiguous_low_confidence_labels':[],'v2b_required':False,'reason':'All coarse groups identified from 24 random samples per label across splits plus ROI supplements. Label 3 medium-high coarse decision, minority mask errors documented; no low-confidence unresolved group affecting >5%. No v2b run.','mapping_status':'Empirical proposal, not official archive schema','reviewed_main_cells':384,'reviewed_total_cells':len(samples),'decision_made_before_extraction':True})
s='# Atlas và quyết định mapping\n\nNguồn/provenance: [../nguon_mapping.md](../nguon_mapping.md). Đã mở và xem đủ atlas nhãn 00–15 cùng 11 bảng phóng vùng bổ sung. 24 mẫu chính mỗi nhãn = 8 train + 8 valid + 8 test, Random(42); không dùng relevance hay điểm baseline để chọn. Bổ sung 12 mẫu khác cho mỗi nhãn 3,4,6,7,8,9,11,12,13,14,15. Các ô giữa nhãn có thể dùng cùng ảnh; không tính chúng là ảnh độc lập.\n\n## Định nghĩa thống kê\n\nnhan_thong_ke.csv ghi số ảnh, tổng pixel, diện tích trung bình (pixel và tỉ lệ), tâm x/y chuẩn hóa. Trung bình tính trên ảnh có nhãn, mỗi ảnh trọng số bằng nhau; x tăng từ trái sang phải, y từ trên xuống, chuẩn hóa bằng W−1/H−1. dong_xuat_hien.csv có số ảnh chứa cả a,b và P(b|a), đủ 16×16 cặp. thong_ke_tung_anh.csv là số liệu gốc để tính lại. Không dùng tâm/diện tích để tự suy ra ngữ nghĩa.\n\n## Mapping đề xuất\n\n| Nhãn | Tên đề xuất | Nhóm | Tin cậy | Quyết định | Ô đã xem |\n|---|---|---|---|---|---:|\n'
for r,rev in zip(proposal,review):s+=f"| {r['nhan']} | {r['ten_vung_de_xuat']} | {r['nhom']} | {r['do_tin_cay']} | {'giữ' if r['nhan'] in keep else 'bỏ'} | {rev['reviewed_main_cells']+rev['reviewed_extra_cells']} |\n"
s+='\nTin cậy là đánh giá trực quan nhóm ngữ nghĩa, không phải độ chính xác thống kê. Cao dựa trên nhiều mẫu ở cả ba split và tính nhất quán của vùng nhìn rõ; không tuyên bố mọi pixel đúng. Nhãn 3 được ghi trung_binh theo schema, hiểu là trung bình-cao cho quyết định giữ tất/quần tất sau khi xem 36 ô; có ngoại lệ nên không ghi cao.\n\n## Kiểm tra chéo split\n\n| Nhãn | Tâm y train / valid / test | Diện tích TB train / valid / test |\n|---|---|---|\n'
for v in range(16):
 ss=[next(r for r in summary if int(r['nhan'])==v and r['split']==sp) for sp in ['train','valid','test']];s+=f"| {v} | {' / '.join(format(float(r['tam_y_tb']),'.4f') for r in ss)} | {' / '.join(format(float(r['dien_tich_tb_ty_le']),'.4f') for r in ss)} |\n"
s+='\nTâm x và biên độ chênh lệch từng đại lượng nằm trong nhan_thong_ke.csv/on_dinh_giua_split.csv. Nhãn 6 và 12 có chênh lệch tâm y lớn hơn các vùng mặt/tóc; túi hoặc phụ kiện eo xuất hiện ở nhiều tư thế, số mẫu hiện diện cũng ít. Atlas không cho thấy một phép đổi mã nhãn khác hẳn theo split. Đây là quan sát mẫu, không chứng minh ổn định trên mọi ảnh.\n\n## Ngoại lệ và mức xác minh\n\n'
for v in range(16):s+=f'- Nhãn {v}: {notes[v]} Bằng chứng: atlas_nhan_{v:02d}.png'+(f' và bo_sung_nhan_{v:02d}.png' if (M/f'bo_sung_nhan_{v:02d}.png').exists() else '')+'.\n'
s+='\nCác ngoại lệ là pixel/vùng gán sai hoặc subtype khác, không phải bằng chứng mọi nhãn đều vô nghĩa. Chưa xác minh được mapping chính thức từ nhà cung cấp và chưa đo chất lượng segmentation trên toàn tập.\n\n## Điểm dừng\n\n**Qua điểm dừng theo nhánh bằng chứng rõ ở cấp nhóm.** Giữ '+str(keep)+'; bỏ [0, 4, 9, 14]. Không còn nhãn nhóm thấp/chưa rõ cần cấu hình v2b; không chạy độ nhạy. Thay đổi duy nhất của v2 so với v1 là tập nhãn giữ: thêm 13/15, bỏ 4/9, 0/14 tiếp tục bị loại. Nhãn 7/12 khác loại phụ kiện nhưng cùng quyết định giữ. Chốt trước khi xem số sanity v2.\n'
(M/'nhan_atlas.md').write_text(s)
print('Mapping review recorded; keep',keep)
